'use strict';const a349_0xf8fd5=a349_0x2d2e;(function(_0x14fe32,_0x28390d){const _0x4530e6=a349_0x2d2e,_0x32d083=_0x14fe32();while(!![]){try{const _0x879a8e=parseInt(_0x4530e6(0x187))/0x1+-parseInt(_0x4530e6(0x18c))/0x2*(parseInt(_0x4530e6(0x18d))/0x3)+parseInt(_0x4530e6(0x189))/0x4+-parseInt(_0x4530e6(0x191))/0x5+-parseInt(_0x4530e6(0x18b))/0x6*(parseInt(_0x4530e6(0x190))/0x7)+-parseInt(_0x4530e6(0x18a))/0x8+parseInt(_0x4530e6(0x192))/0x9;if(_0x879a8e===_0x28390d)break;else _0x32d083['push'](_0x32d083['shift']());}catch(_0x24974b){_0x32d083['push'](_0x32d083['shift']());}}}(a349_0x5314,0x64a8e));function a349_0x2d2e(_0x4651e5,_0x48f320){_0x4651e5=_0x4651e5-0x187;const _0x5314f9=a349_0x5314();let _0x2d2e01=_0x5314f9[_0x4651e5];if(a349_0x2d2e['gXAcjM']===undefined){var _0x196d27=function(_0x35272b){const _0x31630e='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+/=';let _0x29bd51='',_0x1390e1='';for(let _0x15f12e=0x0,_0x2d79d4,_0x3d0629,_0x139e38=0x0;_0x3d0629=_0x35272b['charAt'](_0x139e38++);~_0x3d0629&&(_0x2d79d4=_0x15f12e%0x4?_0x2d79d4*0x40+_0x3d0629:_0x3d0629,_0x15f12e++%0x4)?_0x29bd51+=String['fromCharCode'](0xff&_0x2d79d4>>(-0x2*_0x15f12e&0x6)):0x0){_0x3d0629=_0x31630e['indexOf'](_0x3d0629);}for(let _0x5b8d7e=0x0,_0x514157=_0x29bd51['length'];_0x5b8d7e<_0x514157;_0x5b8d7e++){_0x1390e1+='%'+('00'+_0x29bd51['charCodeAt'](_0x5b8d7e)['toString'](0x10))['slice'](-0x2);}return decodeURIComponent(_0x1390e1);};a349_0x2d2e['NYdNSR']=_0x196d27,a349_0x2d2e['pyZOTM']={},a349_0x2d2e['gXAcjM']=!![];}const _0x20508d=_0x5314f9[0x0],_0x1a991f=_0x4651e5+_0x20508d,_0x2f898a=a349_0x2d2e['pyZOTM'][_0x1a991f];return!_0x2f898a?(_0x2d2e01=a349_0x2d2e['NYdNSR'](_0x2d2e01),a349_0x2d2e['pyZOTM'][_0x1a991f]=_0x2d2e01):_0x2d2e01=_0x2f898a,_0x2d2e01;}function a349_0x5314(){const _0x1cf4b6=['zgvMyxvSDa','ntCYnNzhAe5wDa','mtK1ntGWtw91wwr6','nZGYndCXn2nbrurHza','mZuYnJuYvMXsCgzy','D2vICgfJA0nODw5RD2vIx3rVB2XFDNvL','mJG2nZGZmKHmAxzmAG','mtu0odaWuM1owwTX','ntC2nKruwKL0zq','mZH2sMnYt0i','mta3nZa5r3jiyxbm','ChvZAa'];a349_0x5314=function(){return _0x1cf4b6;};return a349_0x5314();}(self['webpackChunkweb_tool_vue']=self[a349_0xf8fd5(0x188)]||[])[a349_0xf8fd5(0x18e)]([[0x11b4e],{0x11b4e:function(_0x5e83ba,_0x5db70f){const _0x429eee=a349_0xf8fd5,_0x1abea6='<div\x20class=\x22max-w-4xl\x20mx-auto\x20px-4\x20py-8\x20text-gray-800\x22>\x0a\x20\x20<!--\x20文章标题\x20-->\x0a\x20\x20<h1\x20class=\x22text-3xl\x20md:text-4xl\x20font-bold\x20text-center\x20mb-4\x20text-gray-900\x22>还在为搜不到想要的结果烦恼？这个多引擎搜索工具帮你精准定位</h1>\x0a\x20\x20<!--\x20导语\x20-->\x0a\x20\x20<p\x20class=\x22text-lg\x20text-center\x20text-gray-600\x20mb-8\x22>想找资料，却总被广告淹没？搜出来的东西牛头不对马嘴？别急，试试这款能同时用百度、谷歌、必应搜索的小工具，还有几十种“搜索暗号”帮你直达答案。</p>\x0a\x0a\x20\x20<!--\x20正文部分\x20-->\x0a\x20\x20<div\x20class=\x22space-y-8\x22>\x0a\x0a\x20\x20\x20\x20<!--\x20第一部分：搜索痛点\x20-->\x0a\x20\x20\x20\x20<section>\x0a\x20\x20\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20font-semibold\x20mb-3\x20text-gray-900\x20border-l-4\x20border-blue-500\x20pl-3\x22>为什么你总觉得“搜不到”</h2>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22mb-3\x22>你有没有这样的经历：打开百度输入一个词，前几页全是广告和推广，翻半天也找不到真正有用的信息。或者想找一份PDF文档、一个政府网站的文件，结果出来一堆不相关的网页。这不是你搜索的方式不对，而是普通的搜索框太“笨”了，它听不懂你的真实需求。</p>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22mb-3\x22>其实，搜索引擎自己都提供了一些“高级指令”，就像给搜索框下的暗号，可以让它只给你想要的东西。但大多数人不知道这些指令，或者觉得记起来太麻烦。今天要说的这个工具，就是把所有搜索引擎的“暗号”都集成在一起，你只需要点一点，就能用上这些专业功能。</p>\x0a\x20\x20\x20\x20</section>\x0a\x0a\x20\x20\x20\x20<!--\x20第二部分：什么是多引擎智能搜索工具\x20-->\x0a\x20\x20\x20\x20<section>\x0a\x20\x20\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20font-semibold\x20mb-3\x20text-gray-900\x20border-l-4\x20border-blue-500\x20pl-3\x22>一个工具，三个搜索引擎</h2>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22mb-3\x22>这个小工具最直观的地方，就是它把百度、谷歌、必应都放在了一起。你不需要记住三个网址，也不用在不同标签页之间切来切去。想用哪个，点一下按钮就行。</p>\x0a\x20\x20\x20\x20\x20\x20<ul\x20class=\x22list-disc\x20pl-6\x20mb-3\x20space-y-1\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><span\x20class=\x22font-medium\x20text-blue-600\x22>百度</span>：适合搜中文内容，尤其是国内网站的信息。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><span\x20class=\x22font-medium\x20text-blue-600\x22>谷歌</span>：全球最大的搜索引擎，搜外文资料、学术内容特别好用。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><span\x20class=\x22font-medium\x20text-blue-600\x22>必应</span>：微软家的，界面干净，搜图片和视频质量很高。</li>\x0a\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20\x20\x20<p>你可以根据自己需要，随时切换。比如找国内的政策文件用百度，查国外的论文用谷歌，找高清图片用必应。一个入口全搞定。</p>\x0a\x20\x20\x20\x20</section>\x0a\x0a\x20\x20\x20\x20<!--\x20第三部分：高级搜索指令，像说话一样精准\x20-->\x0a\x20\x20\x20\x20<section>\x0a\x20\x20\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20font-semibold\x20mb-3\x20text-gray-900\x20border-l-4\x20border-blue-500\x20pl-3\x22>“搜索暗号”让结果直击要害</h2>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22mb-3\x22>这个工具最厉害的地方，是它自带了几十种“搜索暗号”——也就是搜索引擎的高级指令。你不用死记硬背，因为工具里都列出来了，点一下就能用。下面举几个生活中常见的例子：</p>\x0a\x0a\x20\x20\x20\x20\x20\x20<div\x20class=\x22grid\x20md:grid-cols-2\x20gap-4\x20mt-4\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<!--\x20例子1：搜特定网站\x20-->\x0a\x20\x20\x20\x20\x20\x20\x20\x20<div\x20class=\x22bg-gray-50\x20p-4\x20rounded-lg\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h3\x20class=\x22font-medium\x20text-lg\x20mb-2\x20text-gray-800\x22>只想看某个网站里的内容？用“site:”</h3>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<p\x20class=\x22text-sm\x20text-gray-600\x22>比如你想在知乎上搜“人工智能”，但不想看其他网站，就在关键词前加上<code\x20class=\x22bg-gray-200\x20px-1\x20rounded\x22>site:zhihu.com\x20人工智能</code>。工具里点一下“site:”按钮，再输入网址和关键词就行。</p>\x0a\x20\x20\x20\x20\x20\x20\x20\x20</div>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<!--\x20例子2：搜特定文件\x20-->\x0a\x20\x20\x20\x20\x20\x20\x20\x20<div\x20class=\x22bg-gray-50\x20p-4\x20rounded-lg\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h3\x20class=\x22font-medium\x20text-lg\x20mb-2\x20text-gray-800\x22>想要PDF文档？用“filetype:pdf”</h3>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<p\x20class=\x22text-sm\x20text-gray-600\x22>找工作简历模板、学术论文，往往PDF格式更规范。输入<code\x20class=\x22bg-gray-200\x20px-1\x20rounded\x22>filetype:pdf\x20简历模板</code>，结果就全是PDF文件，省去筛选时间。</p>\x0a\x20\x20\x20\x20\x20\x20\x20\x20</div>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<!--\x20例子3：标题中含有关键词\x20-->\x0a\x20\x20\x20\x20\x20\x20\x20\x20<div\x20class=\x22bg-gray-50\x20p-4\x20rounded-lg\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h3\x20class=\x22font-medium\x20text-lg\x20mb-2\x20text-gray-800\x22>想找标题里带“通知”的网页？用“intitle:”</h3>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<p\x20class=\x22text-sm\x20text-gray-600\x22>如果关键词出现在网页标题里，通常相关性更高。比如搜<code\x20class=\x22bg-gray-200\x20px-1\x20rounded\x22>intitle:放假通知</code>，出来的都是标题中明确有“放假通知”的页面。</p>\x0a\x20\x20\x20\x20\x20\x20\x20\x20</div>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<!--\x20例子4：排除不想要的关键词\x20-->\x0a\x20\x20\x20\x20\x20\x20\x20\x20<div\x20class=\x22bg-gray-50\x20p-4\x20rounded-lg\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<h3\x20class=\x22font-medium\x20text-lg\x20mb-2\x20text-gray-800\x22>想排除广告？用减号“-”</h3>\x0a\x20\x20\x20\x20\x20\x20\x20\x20\x20\x20<p\x20class=\x22text-sm\x20text-gray-600\x22>搜“手机”，但不想看电商广告，可以搜<code\x20class=\x22bg-gray-200\x20px-1\x20rounded\x22>手机\x20-京东\x20-淘宝</code>，结果里就不会出现包含“京东”“淘宝”的页面。</p>\x0a\x20\x20\x20\x20\x20\x20\x20\x20</div>\x0a\x20\x20\x20\x20\x20\x20</div>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22mt-4\x22>还有更多指令，比如搜索特定时间范围、搜索某个网页的缓存、搜索相关网站等等，工具右侧的“高级搜索指令说明”里都列得清清楚楚，点一下就能复制或插入，非常方便。</p>\x0a\x20\x20\x20\x20</section>\x0a\x0a\x20\x20\x20\x20<!--\x20第四部分：实际操作体验\x20-->\x0a\x20\x20\x20\x20<section>\x0a\x20\x20\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20font-semibold\x20mb-3\x20text-gray-900\x20border-l-4\x20border-blue-500\x20pl-3\x22>怎么用？三步搞定</h2>\x0a\x20\x20\x20\x20\x20\x20<ol\x20class=\x22list-decimal\x20pl-6\x20mb-3\x20space-y-2\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>选引擎</strong>：在百度、谷歌、必应中选一个你需要的。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>输关键词</strong>：直接在搜索框里打字，如果要用高级指令，可以点下方的快捷按钮（比如“site:”），指令会自动填入，你再接着输入网址或关键词就行。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>点搜索</strong>：点击右侧的搜索按钮（颜色会随引擎变化），结果就会在新标签页打开。</li>\x0a\x20\x20\x20\x20\x20\x20</ol>\x0a\x20\x20\x20\x20\x20\x20<p>就这么简单。而且你每次搜索，工具都会帮你记录下来（存在你自己的浏览器里，别人看不到）。以后想重复搜同样内容，点一下历史记录就行，不用重新打字。</p>\x0a\x20\x20\x20\x20</section>\x0a\x0a\x20\x20\x20\x20<!--\x20第五部分：小细节让搜索更舒心\x20-->\x0a\x20\x20\x20\x20<section>\x0a\x20\x20\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20font-semibold\x20mb-3\x20text-gray-900\x20border-l-4\x20border-blue-500\x20pl-3\x22>贴心的细节</h2>\x0a\x20\x20\x20\x20\x20\x20<ul\x20class=\x22list-disc\x20pl-6\x20mb-3\x20space-y-1\x22>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>输入提示</strong>：当你开始打字，工具会联想你可能想用的高级指令，选一个就直接填好。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>历史记录</strong>：自动保存最近50次搜索，还能按引擎分类，点一下就能重新搜索。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>使用统计</strong>：你可以看到自己总共搜了多少次，哪个引擎用得最多，有点小成就感。</li>\x0a\x20\x20\x20\x20\x20\x20\x20\x20<li><strong>移动端也能用</strong>：在手机上打开，布局会自动变成上下结构，按钮大小合适，很好点。</li>\x0a\x20\x20\x20\x20\x20\x20</ul>\x0a\x20\x20\x20\x20</section>\x0a\x0a\x20\x20\x20\x20<!--\x20第六部分：总结\x20-->\x0a\x20\x20\x20\x20<section\x20class=\x22bg-blue-50\x20p-6\x20rounded-lg\x22>\x0a\x20\x20\x20\x20\x20\x20<h2\x20class=\x22text-2xl\x20font-semibold\x20mb-3\x20text-gray-900\x22>从现在起，让搜索更聪明</h2>\x0a\x20\x20\x20\x20\x20\x20<p\x20class=\x22mb-3\x22>以前你可能觉得“搜不到”是因为自己不会搜，其实只是没遇到好工具。这个多引擎智能搜索工具，把三大搜索引擎和几十种高级指令集合在一起，不用背、不用记，点一点就能用上“专业搜索”功能。</p>\x0a\x20\x20\x20\x20\x20\x20<p>下次想查资料、找文档、搜图片，不妨试试它。你会发现，原来答案可以离你那么近。</p>\x0a\x20\x20\x20\x20</section>\x0a\x0a\x20\x20\x20\x20<!--\x20附加提示（非营销，纯说明）\x20-->\x0a\x20\x20\x20\x20<p\x20class=\x22text-sm\x20text-gray-500\x20text-center\x20pt-4\x22>——\x20一个让搜索回归纯粹的小工具，不收集任何个人信息，所有历史记录只保存在你的浏览器中。</p>\x0a\x0a\x20\x20</div>\x0a</div>';_0x5db70f[_0x429eee(0x18f)]=_0x1abea6;}}]);